INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q64990796', 'Siege of Petra', 'The siege of Petra took place in 541 when the Sasanian Empire, under King Khosrow I, besieged the town of Petra in Lazica, held by the Byzantine Empire, and it marked the opening stage of the Lazic War. The conflict began after Byzantine Emperor Justinian I, on the advice of one of his officials, John Tzibus, established a fortress at Petra and imposed a trade monopoly on the local population, causing resentment among the citizens of Lazica.', 541, NULL, NULL, NULL, NULL, NULL, 'year', '541', 34, 'https://en.wikipedia.org/wiki/Siege_of_Petra_(541)'),
  ('Q12868103', 'Siege of Petra', 'The Siege of Petra took place in 548/549, when the Byzantine Empire besieged the fortress of Petra in Lazica, which was under the Sasanian Empire. The Sasanian king Khosrow I sought to expand his influence in the Black Sea region and challenge Byzantine naval supremacy by building a navy.', 548, 9, NULL, 549, 1, NULL, 'month', 'September 548 – January 549', 34, 'https://en.wikipedia.org/wiki/Siege_of_Petra_(549)'),
  ('Q61889639', 'Siege of Petra', 'The siege of Petra was fought in 550 AD, between the Byzantines (East Romans) under general Bessas, and the Sasanian Persian garrison of Petra in the buffer state of Lazica. The strategic fortress had previously been held by the Byzantines before it was seized in 541 by the Sasanian king Khosrow I, and his Lazi allies.', 550, NULL, NULL, 551, NULL, NULL, 'year', '550–551', 39, 'https://en.wikipedia.org/wiki/Siege_of_Petra_(550%E2%80%93551)'),
  ('Q7510308', 'Siege of Phasis', 'The siege of Phasis took place in 555–556 during the Lazic War between the Byzantine and Sasanian Empires. Expecting an easy victory, the Persians besieged the town of Phasis in Lazica, held by the Byzantines, but were defeated in the ensuing irregular battle.', 555, 7, NULL, 556, 6, NULL, 'month', 'July 555 – June 556', 43, 'https://en.wikipedia.org/wiki/Siege_of_Phasis'),
  ('Q16379713', 'Siege of Tbilisi', 'The siege of Tbilisi, or Tiflis, was a siege by the Byzantine Empire and western Turkic Khaganate in 627–628 against Prince Stephen I of Iberia, the Sasanid vassal ruler of Sasanian Iberia.', 627, NULL, NULL, 628, NULL, NULL, 'year', '627–628', 45, 'https://en.wikipedia.org/wiki/Siege_of_Tbilisi_(627%E2%80%93628)'),
  ('Q1192616', 'Battle of Didgori', 'The Battle of Didgori (Georgian: დიდგორის ბრძოლა, romanized: didgoris brdzola) was fought between the armies of the Kingdom of Georgia and the Seljuk Empire at the narrow place of Didgori, 40 km west of Tbilisi, on August 12, 1121. The large Muslim army, under the command of Ilghazi, was unable to maneuver and suffered a devastating defeat due to King David IV''s effective military tactics.', 1121, 8, 12, NULL, NULL, NULL, 'day', '12 August 1121', 64, 'https://en.wikipedia.org/wiki/Battle_of_Didgori'),
  ('Q16366324', 'Battle of Bolnisi', 'The Battle of Bolnisi (Georgian: ბოლნისის ბრძოლა) was fought in 1228 AD near Bolnisi, then part of the Kingdom of Georgia. The invading Khwarazmid Empire was led by Jalal al-Din Mangburni, its last Sultan, who was driven from his realm by the Mongol Empire and was trying to recapture lost territories.', 1228, NULL, NULL, NULL, NULL, NULL, 'year', '1228', 34, 'https://en.wikipedia.org/wiki/Battle_of_Bolnisi'),
  ('Q42005', 'Black Death', 'The Black Death was a plague pandemic that occurred in Europe from 1346 to 1353. It was one of the most fatal pandemics in human history, leading to the death of up to 50 million people, around 30% to 60% of the European population and approximately 33% of the Middle Eastern population.', 1346, NULL, NULL, 1352, NULL, NULL, 'year', '1346–1352', 92, 'https://en.wikipedia.org/wiki/Black_Death'),
  ('Q21481366', 'Siege of Tbilisi', 'The siege of Tbilisi was the successful siege of the city of Tbilisi, capital of the Kingdom of Georgia, by the Turco-Mongol conqueror Timur, which ended on 22 November 1386. The official history of his reign, Zafarnama, represents this invasion in Georgia as a jihad.', 1386, NULL, NULL, 1386, 11, 22, 'year', '1386', 34, 'https://en.wikipedia.org/wiki/Siege_of_Tbilisi_(1386)'),
  ('Q2403565', 'Battle of Chikhori', 'The Battle of Chikhori was fought in 1463 between the forces of King George VIII of Georgia and those of the rebel prince Bagrat, claimant to the throne of western Georgia. The battle ended in a decisive victory for Bagrat and his allies among the western Georgian nobility, leading to George VIII’s retreat to eastern Georgia and the effective loss of royal authority in Imereti.', 1463, 8, NULL, NULL, NULL, NULL, 'month', 'August 1463', 41, 'https://en.wikipedia.org/wiki/Battle_of_Chikhori'),
  ('Q4871082', 'Battle of Garisi', 'The Battle of Garisi (Georgian: გარისის ბრძოლა) was fought between the Georgian and Safavid Iranian armies at the village of Garisi (present-day Tetritsqaro) in 1556, and resulted in a stalemate between both sides. This conflict was an immediate consequence of the Treaty of Amasya signed between the Ottoman and Safavid empires in 1555.', 1556, NULL, NULL, NULL, NULL, NULL, 'year', '1556', 41, 'https://en.wikipedia.org/wiki/Battle_of_Garisi'),
  ('Q4872517', 'Battle of Tashiskari', 'The Battle of Tashiskari (Georgian: ტაშისკარის ბრძოლა) was fought between the Georgians and the Ottomans at the village of Tashiskari on June 16, 1609. The Georgians, led by Giorgi Saakadze won a victory over the Ottomans.', 1609, 6, 16, NULL, NULL, NULL, 'day', '16 June 1609', 37, 'https://en.wikipedia.org/wiki/Battle_of_Tashiskari'),
  ('Q5037061', 'Abbas I''s Kakhetian and Kartlian campaigns', 'Abbas I’s Kakhetian and Kartlian campaigns (Georgian: აბას I-ის კახეთისა და ქართლის ლაშქრობები) refers to the four campaigns Safavid Shah Abbas I led between 1614 and 1617, in his East Georgian vassal kingdoms of Kartli and Kakheti during the Ottoman–Safavid War (1603–18). The campaigns were initiated as a response to the shown disobedience and subsequently staged rebellion by Abbas'' formerly most loyal Georgian ghulams, namely Luarsab II of Kartli and Teimuraz I of Kakheti.', 1614, NULL, NULL, 1617, NULL, NULL, 'year', '1614–1617', 43, 'https://en.wikipedia.org/wiki/Abbas_I''s_Kakhetian_and_Kartlian_campaigns'),
  ('Q4870223', 'Battle of Aghaiani', 'The Battle of Aghaiani (Georgian: აღაიანის ბრძოლა; Persian: نبرد آقایانی) was a battle fought in 1625 between the armies of Safavid Iran and the Kingdom of Kakheti. In early spring, Shah Abbas I sent a large Iranian army to Georgia under the command of Qarachaqay Khan, which encamped near the village of Aghaiani.', 1625, NULL, NULL, NULL, NULL, NULL, 'year', '1625', 37, 'https://en.wikipedia.org/wiki/Battle_of_Aghaiani'),
  ('Q4871687', 'Battle of Martqopi', 'The Battle of Martkopi (Georgian: მარტყოფის ბრძოლა) (Persian: نبرد مارتقوپی) was a 1625 military confrontation between the Georgian Kingdoms of Kartli and Kakheti and Safavid Iran. The Georgians, led by general Giorgi Saakadze, annihilated an Iranian detachment of Shah-Abbas I. In spring 1625, in order to avoid a forthcoming revolt, Shah-Abbas I sent his troops into Georgia under the orders of Qarachaqay Khan.', 1625, 3, 25, NULL, NULL, NULL, 'day', '25 March 1625', 39, 'https://en.wikipedia.org/wiki/Battle_of_Martkopi'),
  ('Q4849424', 'Bakhtrioni Uprising', 'The Bakhtrioni uprising (Georgian: ბახტრიონის აჯანყება) was a general revolt in the eastern Georgian Kingdom of Kakheti against the political domination of Safavid Persia, in 1659. Despite the fact that the Persians were able to suppress the uprising later, they were forced to abandon plans to settle Georgia with the Qizilbash.', 1659, 9, NULL, NULL, NULL, NULL, 'month', 'September 1659', 37, 'https://en.wikipedia.org/wiki/Bakhtrioni_uprising'),
  ('Q55627998', 'Ottoman invasion of Western Georgia', 'The 1703 Ottoman invasion of western Georgia was a military expedition undertaken by the Ottoman Empire against the tributary states in western Georgia—Imereti, Guria, and Mingrelia. This considerable military deployment, ostensibly to settle a power struggle in Imereti in favor of the sultan''s candidate, portended a change in Ottoman policy in the fluid frontier region in the Caucasus and aimed at consolidating the imperial authority among the restive Georgian subjects.', 1703, NULL, NULL, NULL, NULL, NULL, 'year', '1703', 37, 'https://en.wikipedia.org/wiki/Ottoman_invasion_of_western_Georgia_(1703)'),
  ('Q2887900', 'Battle of Aspindza', 'The Battle of Aspindza (Georgian: ასპინძის ბრძოლა) was a meeting engagement fought on 20 April 1770 between the Georgians, led by king of Kartli-Kakheti Erekle II, and the Ottoman Empire. The Georgians won a victory over the Turks, defeating them in detail at the river crossing.', 1770, 4, 20, NULL, NULL, NULL, 'day', '20 April 1770', 47, 'https://en.wikipedia.org/wiki/Battle_of_Aspindza'),
  ('Q2615347', 'Battle of Krtsanisi', 'The Battle of Krtsanisi (Georgian: კრწანისის ბრძოლა, romanized: k''rts''anisis brdzola, Persian: نبرد کرتسانیسی) was fought between the army of Qajar Iran (Persia) and the Georgian armies of the Kingdom of Kartli-Kakheti and Kingdom of Imereti at the place of Krtsanisi near Tbilisi, Georgia, from September 8 to September 11, 1795, as part of Agha Mohammad Khan Qajar''s war in response to King Heraclius II of Georgia’s alliance with the Russian Empire. The battle resulted in the decisive defeat of the Georgians, capture, and complete destruction of their capital Tbilisi, as well as the…', 1795, 9, 8, 1795, 9, 11, 'day', '8 September 1795 – 11 September 1795', 55, 'https://en.wikipedia.org/wiki/Battle_of_Krtsanisi'),
  ('Q3486072', 'Battle of Akhalzic', 'The Battle of Akhaltsikhe during the Russo-Turkish War, 1828–1829, may refer to one of the following. Firstly, an offensive battle under the walls of Akhaltsikhe on August 21 (August 9 O.S.), 1828, between 9,000 Russians under Field-Marshal Paskevich on the offensive and 30,000 Turks under Kios-Mahomet-Pasha.', 1828, 8, 9, NULL, NULL, NULL, 'day', '9 August 1828', 39, 'https://en.wikipedia.org/wiki/Battle_of_Akhaltsikhe'),
  ('Q4072912', 'Battle of Akhaltsikhe', 'The Battle of Akhaltsikhe (Russian: Ахалцихское сражение, Georgian: ახალციხის ბრძოლა) occurred on 13 November 1853 during the Crimean War when a Georgian-Russian force of 7,000 defeated a Turkish army of 18,000 men near the Akhaltsikhe fortress in the Caucasus. At the outbreak of the Crimean War, Ali Pasha immediately launched a Turkish offensive to capture the Akhaltsikhe fortress.', 1853, 11, 13, NULL, NULL, NULL, 'day', '13 November 1853', 39, 'https://en.wikipedia.org/wiki/Battle_of_Akhaltsikhe_(1853)'),
  ('Q1936524', 'Bergmann Offensive', 'The Bergmann Offensive (Turkish: Bergmann Taaruzu; in Turkish literature Köprüköy ve Azap Muharebeleri, "Battles of Köprüköy and Azap"; in Russian literature Кёприкейская операция—"Köprüköy operation") was the first engagement of the Caucasus campaign. The first battle after the Russians took Bayazıt during World War I. General Georgy Bergmann, commander of the 1st Caucasus Army Corps, took the initiative against the Ottoman Empire.', 1914, 11, 2, 1914, 11, 17, 'day', '2 November 1914 – 17 November 1914', 47, 'https://en.wikipedia.org/wiki/Bergmann_Offensive'),
  ('Q760629', 'August Uprising', 'The August Uprising (Georgian: აგვისტოს აჯანყება, romanized: agvist''os ajanq''eba) was an unsuccessful insurrection against Soviet rule in the Georgian Soviet Socialist Republic from late August to early September 1924. Aimed at restoring the independence of Georgia from the Soviet Union, the uprising was led by the Committee for Independence of Georgia, a bloc of anti-Soviet political organisations chaired by the Georgian Social Democratic (Menshevik) Party.', 1924, 8, 28, 1924, 9, 5, 'day', '28 August 1924 – 5 September 1924', 63, 'https://en.wikipedia.org/wiki/August_Uprising'),
  ('Q1185525', '1956 Georgian demonstrations', 'The 1956 Georgian demonstrations (Georgian: 1956 წლის საპროტესტო გამოსვლები) were a series of protests against Nikita Khrushchev''s de-Stalinization policy that took place in Tbilisi, capital of the Georgian SSR, Soviet Union, and other cities in the republic from 4 to 10 March 1956. The immediate trigger was the publication of Khrushchev''s "Secret Speech", which criticized Joseph Stalin, the former Soviet leader born in Georgia.', 1956, 3, 9, NULL, NULL, NULL, 'day', '9 March 1956', 59, 'https://en.wikipedia.org/wiki/1956_Georgian_demonstrations'),
  ('Q321780', 'Abkhazia conflict', 'The Abkhazia conflict is a territorial dispute over Abkhazia, a region on the eastern coast of the Black Sea in the South Caucasus, at the intersection of Eastern Europe and Western Asia. The conflict involves Georgia, the Russian Federation and the Russian-backed self-proclaimed Republic of Abkhazia, which is internationally recognised only by Russia, Venezuela, Nicaragua and Syria; Georgia and all other United Nations members consider Abkhazia a sovereign territory of Georgia.', 1989, 3, 18, NULL, NULL, NULL, 'day', '18 March 1989', 61, 'https://en.wikipedia.org/wiki/Abkhazia_conflict'),
  ('Q1194400', 'April 9 tragedy', 'Massacre of Tbilisi (also known as the Tbilisi tragedy or April 9 Tragedy) refers to the events in Tbilisi, Georgian Soviet Socialist Republic, on 9 April 1989, when a peaceful anti-Soviet, pro-independence and nationalist demonstration was violently dispersed by the Soviet Army, resulting in the deaths of 21 Georgian civilians, with hundreds more injured. April 9 is now commemorated in Georgia as the National Unity Day (Georgian: ეროვნული ერთიანობის დღე, romanized: erovnuli ertianobis dghe), an annual public holiday.', 1989, 4, 9, NULL, NULL, NULL, 'day', '9 April 1989', 71, 'https://en.wikipedia.org/wiki/Massacre_of_Tbilisi'),
  ('Q1070890', 'Georgian civil war of 1991–1993', 'The Georgian civil war of 1991–1993 (Georgian: 1991–1993 წლების ქართული სამოქალაქო ომი) lasted from 1991 to 1993 in the South Caucasian country Georgia. It began in December 1991 with the coup against the first democratically-elected President of Georgia, Zviad Gamsakhurdia, by the rebel factions of the Georgian National Guard and the Mkhedrioni paramilitary.', 1991, 12, 22, 1993, 12, 31, 'day', '22 December 1991 – 31 December 1993', 64, 'https://en.wikipedia.org/wiki/Georgian_civil_war_of_1991%E2%80%931993'),
  ('Q1209169', 'War in Abkhazia', 'The War in Abkhazia was fought between Georgian government and paramilitary forces, and a coalition of Abkhaz separatist forces and North Caucasian militants between 1992 and 1993. Ethnic Georgians who lived in Abkhazia fought largely on the side of Georgian government forces.', 1992, 8, 14, 1993, 9, 27, 'day', '14 August 1992 – 27 September 1993', 69, 'https://en.wikipedia.org/wiki/War_in_Abkhazia_(1992%E2%80%931993)'),
  ('Q2671415', 'Battle of Gagra', 'The Battle of Gagra, or Operation Storm was fought between Georgian forces and the Abkhaz secessionists aided by the Confederation of Mountain Peoples of the Caucasus (CMPC) militants from 1 to 6 October 1992, during the War in Abkhazia. The allies, commanded by the Chechen warlord Shamil Basayev, captured the town of Gagra from the undermanned Georgian forces (which were reportedly fewer in numbers but possessed more tanks and armoured personnel carriers) in a surprise attack, leading to an outbreak of ethnic cleansing of local Georgian population.', 1992, 10, 1, 1992, 10, 6, 'day', '1 October 1992 – 6 October 1992', 37, 'https://en.wikipedia.org/wiki/Battle_of_Gagra_(October_1992)'),
  ('Q4390508', 'Dzari Tragedy', 'Dzari Tragedy, Zar Tragedy (Iron Ossetic: Зары трагеди), or the Shooting on the Zar road (Russian: Расстрел на Зарской дороге), was a mass murder of ethnic Ossetian refugees in the administrative territory of Dzari, near the central city of Tskhinvali in Georgia''s break-away South Ossetia region. The event took place on 20 May 1992, when a convoy of refugees from South Ossetia was stopped on the road through Dzari and shot at point-blank from machine guns.', 1992, 5, 20, NULL, NULL, NULL, 'day', '20 May 1992', 39, 'https://en.wikipedia.org/wiki/Dzari_Tragedy'),
  ('Q4430390', 'Sochi agreement', 'The Sochi Agreement (officially titled in Russian: «Соглашение о принципах мирного урегулирования грузино-осетинского конфликта»), also known as the Dagomys Agreement (Дагомысские соглашения), primarily refers to the ceasefire agreement signed by Georgia and Russia in Sochi on June 24, 1992, which ended the South Ossetia War. The term may also refer to other agreements concluded in Sochi, including the Russo-Ukrainian agreement on the division of the Black Sea Fleet on June 23, 1992, the failed ceasefire agreement between Georgia and Russia during the War in Abkhazia on July 27, 1993, and a…', 1992, 6, 24, NULL, NULL, NULL, 'day', '24 June 1992', 41, 'https://en.wikipedia.org/wiki/Sochi_agreement'),
  ('Q609510', 'Ethnic cleansing of Georgians in Sukhumi', 'The Sukhumi massacre took place on 27 September 1993, during and after the fall of Sukhumi into separatist hands in the course of the War in Abkhazia. It was perpetrated against Georgian civilians of Sukhumi, mainly by militia forces of Abkhaz separatists and North Caucasian allies.', 1993, 9, 16, 1993, 9, 27, 'day', '16 September 1993 – 27 September 1993', 43, 'https://en.wikipedia.org/wiki/Ethnic_cleansing_of_Georgians_in_Sukhumi'),
  ('Q3297443', 'Kamani massacre', 'The Battle of Kamani was a battle in the War in Abkhazia (1992–1993), on July 9, 1993. The village was captured and many of its inhabitants were massacred or fled.', 1993, 7, 9, NULL, NULL, NULL, 'day', '9 July 1993', 37, 'https://en.wikipedia.org/wiki/Battle_of_Kamani'),
  ('Q7833750', 'Transair Georgia airliner shootdowns', 'From 20 to 23 September 1993, during the Sukhumi massacre, separatists in Sukhumi, Abkhazia blocked Georgian troops'' overland supply routes as part of the war in Abkhazia. In response, the Georgian government used Sukhumi Babushara Airport to ferry supplies to troops stationed in Sukhumi.', 1993, 9, 23, NULL, NULL, NULL, 'day', '23 September 1993', 47, 'https://en.wikipedia.org/wiki/1993_Sukhumi_airliner_attacks'),
  ('Q137167469', 'Battle of Sukhumi', 'The Fall of Sukhumi or the Siege of Sukhumi occurred from 16 to 27 September 1993, involving the Abkhaz separatists, along with their Russian and North Caucasian backers, and Georgia, being the last engagement of the War in Abkhazia. The battle began on 16 September, when the separatists, aided by the local Russian military base, launched their offensive on Sukhumi, the capital city of the region, amidst the escalation of the Georgian Civil War.', 1993, 9, 16, 1993, 9, 27, 'day', '16 September 1993 – 27 September 1993', 47, 'https://en.wikipedia.org/wiki/Fall_of_Sukhumi'),
  ('Q959303', '1998 War in Abkhazia', 'The 1998 Gali clashes took place in the Gali district of Abkhazia, after ethnic Georgians launched an insurgency against the Abkhazian separatist government. The conflict is sometimes referred to as the Six-Day War of Abkhazia; however, this name only takes into account the Abkhazian offensive that lasted from 20 to 26 May 1998, while hostilities and insurgent attacks had already occurred before that date.', 1998, 5, 20, 1998, 5, 26, 'day', '20 May 1998 – 26 May 1998', 63, 'https://en.wikipedia.org/wiki/1998_Gali_clashes'),
  ('Q120843', 'Second Chechen War', 'The Second Chechen War (Russian: Втора́я чече́нская война́, Chechen: Шолгӏа оьрсийн-нохчийн тӏом, lit. ''Second Russian-Chechen War'') took place in Chechnya and the border regions of the North Caucasus between the Russian Federation and the breakaway Chechen Republic of Ichkeria, from August 1999 to April 2009. In August 1999, Islamists from Chechnya infiltrated Dagestan in Russia.', 1999, 8, 26, 2009, 4, 16, 'day', '26 August 1999 – 16 April 2009', 79, 'https://en.wikipedia.org/wiki/Second_Chechen_War'),
  ('Q1530585', 'Battle for Height 776', 'The Battle for Height 776, part of the larger Battle of Ulus-Kert, was an engagement in the Second Chechen War that took place during fighting for control of the Argun River gorge in the highland Shatoysky District of central Chechnya, between the villages of Ulus-Kert and Selmentauzen. In late February 2000, the Russian military attempted to encircle and destroy a large Chechen force withdrawing from the Chechen capital Grozny to Shatoy and Vedeno in the southern mountains of Chechnya following the 1999–2000 siege and capture of Grozny.', 2000, 2, 29, 2000, 3, 1, 'day', '29 February 2000 – 1 March 2000', 52, 'https://en.wikipedia.org/wiki/Battle_for_Height_776'),
  ('Q182865', 'War in Afghanistan (2001–2021)', 'The war in Afghanistan was a prolonged armed conflict from 2001 to 2021. It began with an invasion by a United States–led coalition under the name Operation Enduring Freedom in response to the September 11 attacks (9/11) carried out by the Taliban-allied and Afghanistan-based al-Qaeda.', 2001, 10, 7, 2021, 8, 30, 'day', '7 October 2001 – 30 August 2021', 84, 'https://en.wikipedia.org/wiki/War_in_Afghanistan_(2001%E2%80%932021)'),
  ('Q41603837', '2002 Tbilisi earthquake', 'The 2002 Tbilisi earthquake occurred on April 25 in the Caucasus country of Georgia. The United States'' National Earthquake Information Center (NEIC) placed the magnitude at 4.3 Ms and 4.8 mb.', 2002, 4, 25, NULL, NULL, NULL, 'day', '25 April 2002', 37, 'https://en.wikipedia.org/wiki/2002_Tbilisi_earthquake'),
  ('Q219470', 'Rose Revolution', 'The Rose Revolution or Revolution of Roses (Georgian: ვარდების რევოლუცია, romanized: vardebis revolutsia) was a nonviolent change of power that occurred in Georgia in November 2003. The event was brought about by widespread protests over the disputed parliamentary elections and culminated in the resignation of President Eduard Shevardnadze, which marked the end of Soviet-era leadership in the country.', 2003, NULL, NULL, NULL, NULL, NULL, 'year', '2003', 75, 'https://en.wikipedia.org/wiki/Rose_Revolution'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q5548075', 'Georgian constitutional referendum, 2003', 'A constitutional referendum was held in Georgia on 2 November 2003 alongside parliamentary elections. The constitutional changes proposed would reduce the number of seats in the next Parliament of Georgia from 235 to 150.', 2003, 11, 2, NULL, NULL, NULL, 'day', '2 November 2003', 37, 'https://en.wikipedia.org/wiki/2003_Georgian_constitutional_referendum'),
  ('Q538398', 'Battle off the coast of Abkhazia', 'The Battle off the coast of Abkhazia was a supposed naval engagement between warships of the Russian Black Sea Fleet and Georgian patrol boats during the Russo-Georgian War.', 2008, 8, 9, 2008, 8, 10, 'day', '9 August 2008 – 10 August 2008', 47, 'https://en.wikipedia.org/wiki/Battle_off_the_coast_of_Abkhazia'),
  ('Q620735', 'Russo-Georgian War', 'The Russo-Georgian War, also known as the Russian invasion of Georgia, was a war waged against Georgia by the Russian Federation and the Russian-backed separatist regions of South Ossetia and Abkhazia in August 2008. The fighting took place in the strategically important South Caucasus region.', 2008, 8, 8, 2008, 8, 12, 'day', '8 August 2008 – 12 August 2008', 84, 'https://en.wikipedia.org/wiki/Russo-Georgian_War'),
  ('Q1764877', 'Occupation of Poti', 'The Occupation of Poti was a series of Russian strikes against the Georgian port of Poti during the Russo-Georgian War in August 2008. The city was later occupied by Russian troops, who remained for some time before eventually withdrawing.', 2008, 9, 13, NULL, NULL, NULL, 'day', '13 September 2008', 41, 'https://en.wikipedia.org/wiki/Occupation_of_Poti'),
  ('Q1797013', 'Georgian referendum', 'A double referendum was held in Georgia on 5 January 2008, alongside presidential elections. One question was a binding referendum on whether to bring forward the 2008 parliamentary elections from October to April/May.', 2008, 1, 5, NULL, NULL, NULL, 'day', '5 January 2008', 47, 'https://en.wikipedia.org/wiki/2008_Georgian_referendum'),
  ('Q1813378', 'Battle of Tskhinvali', 'The Battle of Tskhinvali (2008) (Georgian: ცხინვალის ბრძოლა; Russian: Бои за Цхинвали) was a fight for the city of Tskhinvali, the capital of the self-proclaimed Republic of South Ossetia. It was the only major battle in the Russo-Georgian War.', 2008, 8, 8, 2008, 8, 11, 'day', '8 August 2008 – 11 August 2008', 60, 'https://en.wikipedia.org/wiki/Battle_of_Tskhinvali'),
  ('Q2344156', 'Battle of the Kodori Valley', 'The Battle of the Kodori Valley was a military operation during the Russo-Georgian War in the Upper Kodori Valley of Abkhazia, a breakaway region of Georgia. It was the only part of Abkhazia under Georgian control before this military conflict.', 2008, 8, 9, 2008, 8, 12, 'day', '9 August 2008 – 12 August 2008', 53, 'https://en.wikipedia.org/wiki/Battle_of_the_Kodori_Valley'),
  ('Q18920712', 'War in Afghanistan (2015–2021)', 'The war in Afghanistan was a prolonged armed conflict from 2001 to 2021. It began with an invasion by a United States–led coalition under the name Operation Enduring Freedom in response to the September 11 attacks (9/11) carried out by the Taliban-allied and Afghanistan-based al-Qaeda.', 2015, 1, 1, 2021, 8, 30, 'day', '1 January 2015 – 30 August 2021', 45, 'https://en.wikipedia.org/wiki/War_in_Afghanistan_(2015%E2%80%932021)'),
  ('Q20088998', '2015 Tbilisi flood', 'A significant flood occurred in the Vere River valley in Tbilisi, the capital of Georgia, on the night of 13 to 14 June 2015. It resulted in at least 20 human deaths and struck the Tbilisi Zoo, leaving half of its animal inhabitants either dead or on the loose.', 2015, 6, 14, NULL, NULL, NULL, 'day', '14 June 2015', 59, 'https://en.wikipedia.org/wiki/2015_Tbilisi_flood'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q94698246', '2019–2020 Georgian protests', 'The 2019 protests in Georgia, commonly known as Gavrilov''s Night (Georgian: გავრილოვის ღამე), refers to a series of anti-government and snap election-demanding protests in the country of Georgia.', 2019, NULL, NULL, NULL, NULL, NULL, 'year', '2019', 43, 'https://en.wikipedia.org/wiki/2019_protests_in_Georgia_(country)'),
  ('Q117010346', '2023–2024 Georgian protests', 'In 2023 and 2024, a series of street demonstrations took place throughout Georgia largely in opposition to the proposed "Law on Transparency of Foreign Influence", which would require non-governmental organizations (NGOs) to register as foreign agents or "organizations carrying the interests of a foreign power" and disclose the sources of their income if the funds they receive from abroad amount to more than 20% of their total revenue. The central objection of the protesters was that the law would restrict the Western funding to the non-governmental organizations in Georgia and "alienate"…', 2023, 3, 6, NULL, NULL, NULL, 'day', '6 March 2023', 50, 'https://en.wikipedia.org/wiki/2023%E2%80%932024_Georgian_protests'),
  ('Q131389033', '2023 Georgian protests against "foreign agent" bill', 'In 2023 and 2024, a series of street demonstrations took place throughout Georgia largely in opposition to the proposed "Law on Transparency of Foreign Influence", which would require non-governmental organizations (NGOs) to register as foreign agents or "organizations carrying the interests of a foreign power" and disclose the sources of their income if the funds they receive from abroad amount to more than 20% of their total revenue. The central objection of the protesters was that the law would restrict the Western funding to the non-governmental organizations in Georgia and "alienate"…', 2023, NULL, NULL, NULL, NULL, NULL, 'year', '2023', 60, 'https://en.wikipedia.org/wiki/2023_Georgian_protests'),
  ('Q131144158', '2024–2026 Georgian protests', 'The 2024–2026 Georgian protests (Georgian: საქართველოს საპროტესტო აქციები, romanized: sakartvelos sap’rot’est’o aktsiebi) began on 28 October 2024 after the preliminary official results of the parliamentary election of 26 October were announced. The ruling Georgian Dream party, led by Bidzina Ivanishvili, declared victory according to those results.', 2024, NULL, NULL, NULL, NULL, NULL, 'year', '2024', 61, 'https://en.wikipedia.org/wiki/2024%E2%80%932026_Georgian_protests'),
  ('Q131195437', '2024 Abkhazian protests', 'Protests in the partially recognized Republic of Abkhazia began on 11 November 2024 after the arrest of five opposition activists who opposed an investment agreement with Russia. Protesters blocked roads in Sukhumi and attempted to storm the State Security Service building, demanding the release of detainees.', 2024, 11, 11, 2024, 11, 19, 'day', '11 November 2024 – 19 November 2024', 41, 'https://en.wikipedia.org/wiki/2024_Abkhazian_protests');
